. */
    .b  { fill: var(--accent, #43302E); }
    .bs { stroke: var(--accent, #43302E); fill: none; }
    .e  { fill: var(--bg, #FFF9E3); }
    .es { stroke: var(--bg, #FFF9E3); fill: none; }
    .a  { fill: var(--accent-2, #C1DBE8); }

    .bob {
      animation: rewi-bob 1.6s ease-in-out infinite alternate;
    }
    .antenna {
      transform-box: view-box;
      transform-origin: 80px 42px;
      animation: rewi-wiggle 2.4s ease-in-out infinite;
    }
    .eye {
      transform-box: fill-box;
      transform-origin: center;
      animation: rewi-blink 4s infinite;
    }
    .cheek {
      animation: rewi-blush 3.2s ease-in-out infinite alternate;
    }

    @keyframes rewi-bob {
      from { transform: translateY(0); }
      to   { transform: translateY(-6px); }
    }
    @keyframes rewi-wiggle {
      0%, 100% { transform: rotate(0deg); }
      25%      { transform: rotate(-9deg); }
      60%      { transform: rotate(7deg); }
    }
    @keyframes rewi-blink {
      0%, 90%, 100% { transform: scaleY(1); }
      94%           { transform: scaleY(0.1); }
    }
    @keyframes rewi-blush {
      from { opacity: 0.7; }
      to   { opacity: 1; }
    }

    @media (prefers-reduced-motion: reduce) {
      .bob, .antenna, .eye, .cheek { animation: none; }
    }
